    "content": "const BASE_URL = import.meta.env.VITE_API_URL ?? "https://smartloansbackend.azurewebsites.net";

export interface FactoryArtifact {
  factoryArtifactId: number;
  factoryRunRef: string;
  layer: string;
  iterationNumber: number;
  content: string;
  contentHash?: string;
  layerScore?: number;
  layerPassed?: boolean;
  issuesSummary?: string;
  generatedByModel?: string;
  active: boolean;
  created_At: string;
  updated_at?: string;
}

export interface FactoryArtifactListResponse {
  factoryArtifacts: FactoryArtifact[];
}

// GET ALL — POST /all_factoryArtifacts
export async function getAllFactoryArtifacts(filters?: { factoryRunRef?: string; layer?: string }): Promise<FactoryArtifact[]> {
  const res = await fetch(BASE_URL + "/all_factoryArtifacts", {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({
      factoryArtifacts: [{ ...filters }],
    }),
  });
  if (!res.ok) throw new Error(await res.text());
  const data: FactoryArtifactListResponse = await res.json();
  return data.factoryArtifacts ?? [];
}

// GET ONE — POST /one_factoryArtifacts
export async function getFactoryArtifactById(id: number): Promise<FactoryArtifact> {
  const res = await fetch(BASE_URL + "/one_factoryArtifacts", {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({
      factoryArtifactId: id
    }),
  });
  if (!res.ok) throw new Error(await res.text());
  const data: FactoryArtifactListResponse = await res.json();
  if (!data.factoryArtifacts || data.factoryArtifacts.length === 0) {
    throw new Error(`FactoryArtifact with ID ${id} not found`);
  }
  return data.factoryArtifacts[0];
}

// CREATE — action: 1
export async function createFactoryArtifact(payload: Omit<FactoryArtifact, "factoryArtifactId" | "created_At" | "updated_at">): Promise<FactoryArtifact> {
  const res = await fetch(BASE_URL + "/factoryArtifacts", {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({
      factoryArtifacts: [{ "action": 1, ...payload }],
    }),
  });
  if (!res.ok) throw new Error(await res.text());
  return await res.json();
}

// UPDATE — action: 2
export async function updateFactoryArtifact(id: number, payload: Partial<Omit<FactoryArtifact, "factoryArtifactId" | "created_At" | "updated_at">>): Promise<FactoryArtifact> {
  const res = await fetch(BASE_URL + "/factoryArtifacts", {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({
      factoryArtifacts: [{ "action": 2, "factoryArtifactId": id, ...payload }],
    }),
  });
  if (!res.ok) throw new Error(await res.text());
  return await res.json();
}

// DELETE — action: 3
export async function deleteFactoryArtifact(id: number): Promise<void> {
  const res = await fetch(BASE_URL + "/factoryArtifacts", {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({
      factoryArtifacts: [{ "action": 3, "factoryArtifactId": id }],
    }),
  });
  if (!res.ok) throw new Error(await res.text());
}
