  IonInput,
  IonSelect,
  IonSelectOption,
  IonTextarea,
  IonBadge,
  IonSearchbar,
  IonInfiniteScroll,
  IonInfiniteScrollContent,
  IonAlert
} from '@ionic/react';
import { addOutline, createOutline, trashOutline, closeOutline, informationCircleOutline, chevronForward, checkmark, checkmarkCircle } from 'ionicons/icons';
import Header from '../components/Header';
import AlertPopover from '../components/PopOver/AlertPopover';
import MailPopover from '../components/PopOver/MailPopover';
import { useUser } from '../components/UserContext';
import { FactoryArtifact, getAllFactoryArtifacts, getFactoryArtifactById, createFactoryArtifact, updateFactoryArtifact, deleteFactoryArtifact } from '../api/factoryArtifactApi';
import { InputInputEventDetail, SearchbarInputEventDetail, SelectChangeEventDetail } from '@ionic/core';

const toHermosillo = (utc: string | undefined): string => {
  if (!utc) return '';
  const d = new Date(utc.includes('Z') ? utc : utc + 'Z');
  return new Date(d.getTime() - 7 * 60 * 60 * 1000).toLocaleString();
};

const FactoryArtifactPage: React.FC = () => {
  const { roleCode } = useUser();
  const [factoryArtifacts, setFactoryArtifacts] = useState<FactoryArtifact[]>([]);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState('');
  const [searchTerm, setSearchTerm] = useState('');
  const [selectedLayer, setSelectedLayer] = useState<string | undefined>(undefined);
  const [showCreateModal, setShowCreateModal] = useState(false);
  const [showDetailModal, setShowDetailModal] = useState(false);
  const [editingArtifact, setEditingArtifact] = useState<FactoryArtifact | null>(null);
  const [detailArtifact, setDetailArtifact] = useState<FactoryArtifact | null>(null);
  const [formState, setFormState] = useState<Omit<FactoryArtifact, 'factoryArtifactId' | 'created_At' | 'updated_at'>>({
    factoryRunRef: '',
    layer: '',
    iterationNumber: 1,
    content: '',
    active: true,
  });
  const [popoverState, setPopoverState] = useState({
    showAlertPopover: false,
    showMailPopover: false,
    event: undefined as Event | undefined,
  });
  const [isInfiniteDisabled, setInfiniteDisabled] = useState(false);
  const [currentPage, setCurrentPage] = useState(0);
  const ITEMS_PER_PAGE = 20;

  const presentAlertPopover = (e: React.MouseEvent) =>
    setPopoverState({ ...popoverState, showAlertPopover: true, event: e.nativeEvent });
  const dismissAlertPopover = () =>
    setPopoverState({ ...popoverState, showAlertPopover: false });
  const presentMailPopover = (e: React.MouseEvent) =>
    setPopoverState({ ...popoverState, showMailPopover: true, event: e.nativeEvent });
  const dismissMailPopover = () =>
    setPopoverState({ ...popoverState, showMailPopover: false });

  const canEdit = roleCode === 'Admin';

  const loadFactoryArtifacts = async (page: number, append = false) => {
    setLoading(true);
    try {
      const filters: { factoryRunRef?: string, layer?: string } = {};
      if (searchTerm) filters.factoryRunRef = searchTerm;
      if (selectedLayer) filters.layer = selectedLayer;

      const allArtifacts = await getAllFactoryArtifacts(filters);
      // Simple client-side pagination for demonstration, as backend doesn't support offset/limit yet
      const start = page * ITEMS_PER_PAGE;
      const end = start + ITEMS_PER_PAGE;
      const newItems = allArtifacts.slice(start, end);

      if (append) {
        setFactoryArtifacts((prev) => [...prev, ...newItems]);
      } else {
        setFactoryArtifacts(newItems);
      }
      setInfiniteDisabled(newItems.length < ITEMS_PER_PAGE);
      setCurrentPage(page);
    } catch (err) {
      setError((err as Error).message ?? 'Error loading factory artifacts');
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    loadFactoryArtifacts(0);
  }, [searchTerm, selectedLayer]);

  const loadMoreItems = async () => {
    await loadFactoryArtifacts(currentPage + 1, true);
  };

  const handleCreateClick = () => {
    setEditingArtifact(null);
    setFormState({
      factoryRunRef: '',
      layer: '',
      iterationNumber: 1,
      content: '',
      active: true,
      contentHash: '',
      layerScore: undefined,
      layerPassed: undefined,
      issuesSummary: '',
      generatedByModel: '',
    });
    setShowCreateModal(true);
  };

  const handleEditClick = async (id: number) => {
    setLoading(true);
    try {
      const artifact = await getFactoryArtifactById(id);
      setEditingArtifact(artifact);
      setFormState({
        factoryRunRef: artifact.factoryRunRef,
        layer: artifact.layer,
        iterationNumber: artifact.iterationNumber,
        content: artifact.content,
        active: artifact.active,
        contentHash: artifact.contentHash || '',
        layerScore: artifact.layerScore,
        layerPassed: artifact.layerPassed,
        issuesSummary: artifact.issuesSummary || '',
        generatedByModel: artifact.generatedByModel || '',
      });
      setShowCreateModal(true);
    } catch (err) {
      setError((err as Error).message ?? 'Error loading artifact for edit');
    } finally {
      setLoading(false);
    }
  };

  const handleViewDetails = async (id: number) => {
    setLoading(true);
    try {
      const artifact = await getFactoryArtifactById(id);
      setDetailArtifact(artifact);
      setShowDetailModal(true);
    } catch (err) {
      setError((err as Error).message ?? 'Error loading artifact details');
    } finally {
      setLoading(false);
    }
  };

  const handleSaveArtifact = async () => {
    setLoading(true);
    try {
      if (editingArtifact) {
        await updateFactoryArtifact(editingArtifact.factoryArtifactId, formState);
      } else {
        await createFactoryArtifact(formState);
      }
      setShowCreateModal(false);
      await loadFactoryArtifacts(0); // Refresh list
    } catch (err) {
      setError((err as Error).message ?? 'Error saving artifact');
    } finally {
      setLoading(false);
    }
  };

  const [showDeleteAlert, setShowDeleteAlert] = useState(false);
  const [artifactToDelete, setArtifactToDelete] = useState<number | null>(null);

  const handleDeleteClick = (id: number) => {
    setArtifactToDelete(id);
    setShowDeleteAlert(true);
  };

  const confirmDelete = async () => {
    if (artifactToDelete === null) return;
    setLoading(true);
    try {
      await deleteFactoryArtifact(artifactToDelete);
      setShowDeleteAlert(false);
      setArtifactToDelete(null);
      await loadFactoryArtifacts(0); // Refresh list
    } catch (err) {
      setError((err as Error).message ?? 'Error deleting artifact');
    } finally {
      setLoading(false);
    }
  };

  return (
    <IonPage>
      <Header
        presentAlertPopover={presentAlertPopover}
        presentMailPopover={presentMailPopover}
        screenTitle="Artefactos de Fábrica — POS GMO"
      />
      <AlertPopover
        isOpen={popoverState.showAlertPopover}
        event={popoverState.event}
        onDidDismiss={dismissAlertPopover}
      />
      <MailPopover
        isOpen={popoverState.showMailPopover}
        event={popoverState.event}
        onDidDismiss={dismissMailPopover}
      />

      <IonContent fullscreen className="factory-artifact-page">
        <IonLoading isOpen={loading} message="Cargando..." />
        <IonToast
          isOpen={!!error}
          message={error}
          duration={3000}
          onDidDismiss={() => setError('')}
          color="danger"
        />

        <div className="factory-artifact-filters">
          <IonSearchbar
            value={searchTerm}
            onIonInput={(e: CustomEvent<SearchbarInputEventDetail>) => setSearchTerm(e.detail.value!)}
            placeholder="Buscar por Factory Run Ref"
            debounce={300}
          />
          <IonSelect
            value={selectedLayer}
            placeholder="Filtrar por Capa"
            onIonChange={(e: CustomEvent<SelectChangeEventDetail>) => setSelectedLayer(e.detail.value!)}
            fill="outline"
            label="Capa"
            labelPlacement="floating"
          >
            <IonSelectOption value={undefined}>Todas las Capas</IonSelectOption>
            <IonSelectOption value="database">Database</IonSelectOption>
            <IonSelectOption value="backend">Backend</IonSelectOption>
            <IonSelectOption value="frontend">Frontend</IonSelectOption>
          </IonSelect>
        </div>

        <IonList className="factory-artifact-list">
          {factoryArtifacts.length === 0 && !loading && <p className="ion-text-center">No hay artefactos para mostrar.</p>}
          {factoryArtifacts.map((artifact) => (
            <IonItem key={artifact.factoryArtifactId} detail onClick={() => handleViewDetails(artifact.factoryArtifactId)}>
              <IonIcon icon={informationCircleOutline} slot="start" />
              <IonLabel>
                <h2>{artifact.factoryRunRef} - {artifact.layer} (Iteración: {artifact.iterationNumber})</h2>
                <p>Generado por: {artifact.generatedByModel || 'Desconocido'}</p>
                <p>Creado el: {toHermosillo(artifact.created_At)}</p>
                {artifact.issuesSummary && <p>Resumen de problemas: {artifact.issuesSummary.substring(0, 100)}{artifact.issuesSummary.length > 100 ? '...' : ''}</p>}
                <div className="artifact-badges">
                  {artifact.layerScore !== undefined && (
                    <IonBadge color="medium">Score: {artifact.layerScore}</IonBadge>
                  )}
                  {artifact.layerPassed !== undefined && (
                    <IonBadge color={artifact.layerPassed ? "success" : "danger"}>
                      {artifact.layerPassed ? "Pasó" : "Falló"}
                    </IonBadge>
                  )}
                </div>
              </IonLabel>
              {canEdit && (
                <IonButton slot="end" fill="clear" onClick={(e) => { e.stopPropagation(); handleEditClick(artifact.factoryArtifactId); }}>
                  <IonIcon icon={createOutline} />
                </IonButton>
              )}
              {canEdit && (
                <IonButton slot="end" fill="clear" color="danger" onClick={(e) => { e.stopPropagation(); handleDeleteClick(artifact.factoryArtifactId); }}>
                  <IonIcon icon={trashOutline} />
                </IonButton>
              )}
            </IonItem>
          ))}
        </IonList>

        <IonInfiniteScroll onIonInfinite={(ev: CustomEvent<void>) => {
          loadMoreItems();
          (ev.target as HTMLIonInfiniteScrollElement).complete();
        }} disabled={isInfiniteDisabled}>
          <IonInfiniteScrollContent loadingText="Cargando más artefactos..."></IonInfiniteScrollContent>
        </IonInfiniteScroll>

        <IonFab vertical="bottom" horizontal="end" slot="fixed">
          <IonFabButton onClick={handleCreateClick} disabled={!canEdit}>
            <IonIcon icon={addOutline} />
          </IonFabButton>
        </IonFab>

        {/* Create/Edit Modal */}
        <IonModal isOpen={showCreateModal} onDidDismiss={() => setShowCreateModal(false)} className="factory-artifact-modal">
          <IonHeader>
            <IonToolbar>
              <IonTitle>{editingArtifact ? 'Editar Artefacto' : 'Crear Nuevo Artefacto'}</IonTitle>
              <IonButtons slot="end">
                <IonButton onClick={() => setShowCreateModal(false)}>
