              <div className="factory-artifact-detail-card">
                <IonItem>
                  <IonLabel><h2>Factory Run Ref:</h2><p>{detailArtifact.factoryRunRef}</p></IonLabel>
                </IonItem>
                <IonItem>
                  <IonLabel><h2>Capa:</h2><p>{detailArtifact.layer}</p></IonLabel>
                </IonItem>
                <IonItem>
                  <IonLabel><h2>Iteración:</h2><p>{detailArtifact.iterationNumber}</p></IonLabel>
                </IonItem>
                <IonItem>
                  <IonLabel><h2>Generado por Modelo:</h2><p>{detailArtifact.generatedByModel || 'N/A'}</p></IonLabel>
                </IonItem>
                <IonItem>
                  <IonLabel><h2>Content Hash:</h2><p>{detailArtifact.contentHash || 'N/A'}</p></IonLabel>
                </IonItem>
                {detailArtifact.layerScore !== undefined && (
                  <IonItem>
                    <IonLabel><h2>Puntuación de Capa:</h2><p>{detailArtifact.layerScore}</p></IonLabel>
                  </IonItem>
                )}
                {detailArtifact.layerPassed !== undefined && (
                  <IonItem>
                    <IonLabel><h2>Capa Pasó?:</h2><p>{detailArtifact.layerPassed ? 'Sí' : 'No'}</p></IonLabel>
                  </IonItem>
                )}
                {detailArtifact.issuesSummary && (
                  <IonItem>
                    <IonLabel><h2>Resumen de Problemas:</h2><p>{detailArtifact.issuesSummary}</p></IonLabel>
                  </IonItem>
                )}
                <IonItem>
                  <IonLabel><h2>Creado El:</h2><p>{toHermosillo(detailArtifact.created_At)}</p></IonLabel>
                </IonItem>
                {detailArtifact.updated_at && (
                  <IonItem>
                    <IonLabel><h2>Actualizado El:</h2><p>{toHermosillo(detailArtifact.updated_at)}</p></IonLabel>
                  </IonItem>
                )}
                <h2 className="detail-content-heading">Contenido:</h2>
                <pre className="artifact-content-code"><code>{detailArtifact.content}</code></pre>
              </div>
            )}
          </IonContent>
        </IonModal>

        {/* Delete Confirmation Alert */}
        <IonAlert
          isOpen={showDeleteAlert}
          onDidDismiss={() => setShowDeleteAlert(false)}
          header={'Confirmar Eliminación'}
          message={'¿Estás seguro de que quieres eliminar este artefacto?'}
          buttons={[
            { text: 'Cancelar', role: 'cancel' },
            { text: 'Eliminar', handler: confirmDelete, cssClass: 'danger' },
          ]}
        />
      </IonContent>
    </IonPage>
  );
};

export default FactoryArtifactPage;
